```go
package main

import (
	"fmt"
	"go/ast"
	"go/token"
	"io/ioutil"
	"os"
)

// Define a function to read a struct definition from a Go source file.
func readStructDefinition(filename string) (*ast.StructType, error) {
	file, err := os.Open(filename)
	if err != nil {
		return nil, err
	}
	defer file.Close()

	tok := token.NewFileSet()
	tree, err := parser.ParseFile(tok, filename, file, 0)
	if err != nil {
		return nil, err
	}

	for _, decl := range tree.Decls[1:] { // Skip import declaration
		if d, ok := decl.(*ast.GenDecl); ok {
			if d.Tok == token.TYPE && len(d.Specs) > 0 {
				specs := d.Specs[0].(*ast.TypeSpec)
				if t, ok := specs.Type.(*ast.StructType); ok {
					return t, nil
				}
			}
		}
	}

	return nil, fmt.Errorf("no struct found")
}

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run main.go <source_file> <struct_name>")
		os.Exit(1)
	}

	filename := os.Args[1]
	structName := os.Args[2]

	structDef, err := readStructDefinition(filename)
	if err != nil {
		fmt.Printf("Error reading struct definition: %v\n", err)
		os.Exit(1)
	}

	avscPath := "struct.avsc"

	// Write the Avro schema to the output file
	err = ioutil.WriteFile(avscPath, []byte(fmt.Sprintf(`%s {\n%s\n}`, structName, ast.ToText(structDef))), 0644)
	if err != nil {
		fmt.Printf("Error writing Avro schema: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Avro schema written to '%s'\n", avscPath)
}
```

